1	import { voiceMeasurements, VOICE_REVISION, type VoiceMeasurement } from './voiceMeasurements';
2	export interface LocalSpeech { samples: Float32Array; sampleRate: number; generationMs?: number; backend?: string; clipReuse?: boolean }
3	export interface VoiceGraphProgress { file: string; backend: string; operation: 'session' | 'run'; state: 'start' | 'complete' | 'error'; completed: number; expected?: number; startedAt: number; durationMs?: number }
4	export interface VoiceStatus {
5	  phase: 'idle' | 'loading' | 'preparing' | 'ready' | 'synthesizing' | 'error';
6	  message: string;
7	  loadedBytes?: number;
8	  totalBytes?: number;
9	  file?: string;
10	  files?: { file: string; loadedBytes: number; totalBytes: number; source: 'cache' | 'network' | 'unknown' }[];
11	  graphs?: VoiceGraphProgress[];
12	  startedAt?: number;
13	  confirmedAt?: number;
14	  runtimeEvent?: boolean;
15	  heartbeatAt?: number;
16	}
17	let status: VoiceStatus = { phase: 'idle', message: 'Supertonic local voice · downloads on first use' };
18	const listeners = new Set<(value: VoiceStatus) => void>();
19	let worker: Worker | null = null;
20	let nextId = 0;
21	const pending = new Map<number, { resolve: (audio: LocalSpeech | null) => void; reject: (error: Error) => void; timer: ReturnType<typeof setTimeout> }>();
22	let preload: Promise<void> | null = null;
23	// A failed GPU runtime is unsafe to reuse. The next explicit retry stays local
24	// but uses WASM for the rest of this page session.
25	let forceWasm = false;
26	
27	export function reportVoiceStatus(value: VoiceStatus) {
28	  status = value.phase === 'error' ? { ...status, ...value } : { heartbeatAt: status.heartbeatAt, ...value };
29	  for (const listener of listeners) listener(status);
30	}
31	export function subscribeVoiceStatus(listener: (value: VoiceStatus) => void) {
32	  listeners.add(listener);
33	  listener(status);
34	  return () => { listeners.delete(listener); };
35	}
36	function resetWorker(message: string, recordInterruption = true) {
37	  if (pending.size && recordInterruption) voiceMeasurements.record({ operation: 'request', state: 'error', runId: 'worker-interruption-' + nextId, revision: VOICE_REVISION });
38	  worker?.terminate();
39	  worker = null;
40	  preload = null;
41	  for (const request of pending.values()) {
42	    clearTimeout(request.timer);
43	    request.reject(new Error(message));
44	  }
45	  pending.clear();
46	  reportVoiceStatus({ phase: 'error', message });
47	}
48	export function splitSpeechText(text: string, limit = 300): string[] {
49	  if (!Number.isInteger(limit) || limit < 10 || limit > 1000) throw new Error('Invalid speech chunk limit.');
50	  const normalized = text.trim().replace(/\s+/g, ' ');
51	  const chunks: string[] = [];
52	  let current = '';
53	  for (let sentence of normalized.split(/(?<=[.!?])\s+/u)) {
54	    if (!sentence) continue;
55	    if (current && current.length + sentence.length + 1 > limit) {
56	      chunks.push(current);
57	      current = '';
58	    }
59	    while (sentence.length > limit) {
60	      const prefix = sentence.slice(0, limit + 1);
61	      const clause = [...prefix.matchAll(/[,;:] /g)].at(-1);
62	      const boundary = clause && clause.index! >= limit / 2 ? clause.index! + 1 : prefix.lastIndexOf(' ');
63	      let end = boundary > 0 ? boundary : limit;
64	      // Do not split a Unicode surrogate pair, even in an overlong single word.
65	      if (/[\uD800-\uDBFF]/.test(sentence[end - 1]) && /[\uDC00-\uDFFF]/.test(sentence[end])) end--;
66	      chunks.push(sentence.slice(0, end));
67	      sentence = sentence.slice(end).trimStart();
68	    }
69	    current = current ? current + ' ' + sentence : sentence;
70	  }
71	  if (current) chunks.push(current);
72	  return chunks;
73	}
74	function requestWorker(payload: { text?: string; preload?: boolean; voice?: string; speed?: number }): Promise<LocalSpeech | null> {
75	  if (!worker) {
76	    try {
77	      worker = new Worker(new URL('./supertonic.worker.ts', import.meta.url), { type: 'module' });
78	      const activeWorker = worker;
79	      worker.onmessage = ({ data }) => {
80	        if (worker !== activeWorker) return;
81	        if (data.measurement) {
82	          if (data.measurement.operation === 'request' && data.measurement.state === 'start') reportVoiceStatus({ ...status, heartbeatAt: undefined });
83	          voiceMeasurements.record(data.measurement as VoiceMeasurement);
84	        }
85	        if (data.heartbeat) reportVoiceStatus({ ...status, heartbeatAt: data.heartbeat });
86	        if (data.status) reportVoiceStatus(data.status);
87	        if (!data.id) return;
88	        const request = pending.get(data.id);
89	        if (!request) return;
90	        if (data.error) {
91	          if (data.runtimeFailed && data.backend === 'webgpu') forceWasm = true;
92	          resetWorker(data.error, false);
93	          return;
94	        }
95	        clearTimeout(request.timer);
96	        pending.delete(data.id);
97	        request.resolve(data.preloaded ? null : {
98	          samples: data.samples, sampleRate: data.sampleRate,
99	          ...(Number.isFinite(data.generationMs) ? { generationMs: data.generationMs } : {}),
100	          ...(['wasm', 'webgpu'].includes(data.backend) ? { backend: data.backend } : {}),
101	          ...(typeof data.clipReuse === 'boolean' ? { clipReuse: data.clipReuse } : {}),
102	        });
103	      };
104	      worker.onerror = () => {
105	        if (worker === activeWorker) resetWorker('Local voice could not start. Retry voice preview.');
106	      };
107	      worker.onmessageerror = () => {
108	        if (worker === activeWorker) resetWorker('Local voice returned unreadable data. Retry voice preview.');
109	      };
110	    } catch {
111	      return Promise.reject(new Error('This browser cannot start local voice.'));
112	    }
113	  }
