  color: var(--brass-bright, #d9b878);
}
.nv-retry {
  flex: 0 0 auto;
  font: inherit;
  font-size: 10px;
  color: var(--brass-bright, #d9b878);
  background: transparent;
  border: 1px solid var(--brass-dim, #6f5a35);
  border-radius: 999px;
  padding: 1px 10px;
  cursor: pointer;
}
